def is_one_edit_away(a, b):
    la, lb = len(a), len(b)
    if abs(la - lb) > 1:
        return False
    if a == b:
        return True
    if la == lb:
        mismatches = [i for i in range(la) if a[i] != b[i]]
        return len(mismatches) == 1
    shorter, longer = (a, b) if la < lb else (b, a)
    for i in range(len(longer)):
        candidate = longer[:i] + longer[i + 1:]
        if candidate == shorter:
            return True
    return False

def utc_to_local(hh, mm, utc_offset_minutes):
    minute_of_day = hh * 60 + mm
    shifted = minute_of_day + utc_offset_minutes
    day_delta = 0
    while shifted < 0:
        shifted += 1440
        day_delta -= 1
    while shifted >= 1440:
        shifted -= 1440
        day_delta += 1
    return (shifted // 60, shifted % 60, day_delta)

