def is_palindrome_in_base(n, base):
    digits = []
    x = n
    if x == 0:
        digits.append(0)
    while x > 0:
        digits.append(x % base)
        x //= base
    lo, hi = 0, len(digits) - 1
    while lo < hi:
        if digits[lo] != digits[hi]:
            return False
        lo += 1
        hi -= 1
    return True

