def count_goldbach_pairs(n):
    sieve = [True] * (n + 1)
    sieve[0:2] = [False, False]
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            for multiple in range(i * i, n + 1, i):
                sieve[multiple] = False
    count = 0
    for p in range(2, n // 2 + 1):
        if sieve[p] and sieve[n - p]:
            count += 1
    return count

