def proper_divisors(n):
    n = abs(n)
    small = []
    large = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            j = n // i
            if i != n:
                small.append(i)
            if j != i and j != n:
                large.append(j)
        i += 1
    large.sort()
    return small + large
